-- 418: Original BrillaPrep WASSCE Integrated Science beta questions, part 6 of 8 (sprint 1 batch 001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_418_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_418_guard;
INSERT INTO _migration_418_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_bio_b001_007' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_bio' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Bile helps the digestion of fats by:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Chemically breaking fat molecules into fatty acids and glycerol","B. Neutralising all the acid produced in the stomach","C. Converting fats into glucose for easy absorption","D. Emulsifying the fats — breaking large fat globules into smaller droplets"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Bile salts break large fat globules into small droplets (emulsification), increasing the surface area for lipase to act. Bile contains no enzyme; lipase does the chemical breakdown of fats.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_bio_b001_007' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_418_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_bio_b001_008' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_bio' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The end product of protein digestion that is absorbed into the blood is:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Amino acids","B. Glucose","C. Fatty acids and glycerol","D. Maltose"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Proteins are digested by pepsin, trypsin and peptidases into amino acids, which are small and soluble enough to be absorbed. Glucose comes from carbohydrates; fatty acids and glycerol come from fats.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_bio_b001_008' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_418_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_hlt_b001_001' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Malaria is transmitted to humans through the bite of an infected:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Male Culex mosquito","B. Tsetse fly","C. Female Anopheles mosquito","D. Housefly"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Only female mosquitoes take blood meals, and the female Anopheles mosquito carries the Plasmodium parasite. The tsetse fly transmits sleeping sickness and houseflies spread diarrhoeal diseases.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_hlt_b001_001' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_418_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_hlt_b001_002' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Cholera is commonly spread when people:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Are bitten by infected mosquitoes","B. Inhale droplets from a coughing patient","C. Touch the skin of an infected person","D. Drink water or eat food contaminated with faeces"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Cholera bacteria pass out in the faeces of patients and contaminate drinking water or food, infecting the next person who swallows them. Cholera is not spread by mosquitoes, droplets or casual contact.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_hlt_b001_002' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_418_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_hlt_b001_003' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a non-communicable disease?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Diabetes mellitus","B. Tuberculosis","C. Measles","D. Cholera"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Diabetes mellitus results from the body failing to control blood glucose properly and cannot pass from person to person. Tuberculosis, measles and cholera are communicable diseases caused by pathogens.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_hlt_b001_003' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_418_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_hlt_b001_004' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Vaccination protects a person against a disease mainly by:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Instantly killing all the germs in the blood","B. Stimulating the body to produce antibodies before infection occurs","C. Replacing infected blood with healthy blood","D. Making the skin completely germ-proof"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A vaccine introduces a harmless form of the pathogen (or part of it), so the immune system makes antibodies and memory cells that respond rapidly if the real pathogen arrives later.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_hlt_b001_004' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
